// Fragenpool für die Probeprüfungen. Format wie in der echten Prüfung:
// "einfach" = eine richtige Antwort, "mehrfach" = genau so viele richtige wie in richtig (die Frage sagt, wie viele),
// "eingabe" = Lückentext, die Antwort wird getippt (Groß-/Kleinschreibung zählt bei Befehlen nicht, Leerzeichen am Rand egal).
// Alle Fragen sind selbst geschrieben. Es sind keine echten Prüfungsfragen (die sind vertraulich).
// IDs nie ändern: Der Lernstand hängt daran.

export interface Frage {
  id: string;
  ziel: string;
  typ: 'einfach' | 'mehrfach' | 'eingabe';
  frage: string;
  optionen?: string[];
  richtig: (number | string)[];   // Indizes der Optionen oder erlaubte Eingaben
  erklaerung: string;
}

